"""Builds AUDIT-336.md from audit.json (+ curricula for the 198 denominator). Deterministic."""
import json,glob,collections
A=json.load(open('tools/mathematics/core/audit/audit.json'))
R=A['rows'];F=A['families'];rc=A['reconciliation']
cb=set()
for f in glob.glob('content/learning/curricula/cbse-ncert-mathematics-grade-*.json'):
    for s in json.load(open(f)).get('subjects',[]):
        for c in s.get('chapters',[]):
            for o in c.get('outcomes',[]):
                for k in (o.get('mapping') or {}).get('competencies',[]): cb.add(k['id'] if isinstance(k,dict) else k)
mat={r['id'] for r in R}
anyv=sum(1 for r in R if r['kernel']+r['partial']>0); anyk=sum(1 for r in R if r['kernel']>0)
strand=lambda f:f['competency'].split('.')[1]
S=collections.OrderedDict()
for r in sorted(R,key=lambda r:r['strand']):
    s=S.setdefault(r['strand'],[0,0,0,0,0,0,0])
    s[0]+=1;s[1]+=r['nFamilies'];s[2]+=r['kernel'];s[3]+=r['partial'];s[4]+=r['compat']+r['none'];s[5]+=r['volume'];s[6]+=r['verifiedVolume']
ops=collections.defaultdict(lambda:[0,0])
for f in F.values():
    for o in f['unverifiedOps']: ops[o][0]+=1; ops[o][1]+=f['poolSize']
L=[]
L.append("# 336-competency capability audit\n\nGenerated by `tools/mathematics/core/audit/audit.ts` + `report.py` (read-only; no family, dataset or verifier was changed). Data: `audit.json`.\n")
L.append("## 1. Reconciliation of the counts (different denominators)\n")
L.append("| Count | Value | What it counts |\n|---|---|---|")
L+= [f"| Requirements | {rc['requirements']} | CBSE + Tamil Nadu outcomes, Grades 1–12 (coverage matrix) |",
 f"| Required competencies | {rc['competenciesInMatrix']} | distinct competencies those requirements map to; the rows of this audit |",
 f"| CBSE/NCERT maths-mapped competencies | {len(cb)} | distinct competency ids in the CBSE maths curriculum files ({len(cb&mat)} are among the 336) |",
 f"| Families | {rc['familiesTotal']} | generators in `FAMILIES`; {rc['distinctFamiliesInMatrix']} are referenced by the matrix, {rc['familiesNotInMatrix']} are not |",
 f"| Kernel-backed families | {rc['kernel']} | every sampled step passes a `verify()` function |",
 f"| Partially adapted families | {rc['partial']} | some steps verified, others not |",
 f"| Compatibility-mode families | {rc['compat']} | no step verified by the kernel (generator's own answer and `validate` only) |",
 f"| Families without a solvable sample | {rc['none']} | no problem produced by the classifier |",
 f"| Pool problems | {rc['poolProblemsAllFamilies']} | released typed questions over all families |",
 f"| Competencies with ≥1 kernel or partial family | {anyv} | an upper bound on 'has any verification' |",
 f"| Competencies with ≥1 kernel-backed family | {anyk} | |",
 f"| Competencies with all families kernel-backed | {rc['competencyStatus']['all-verified']} | |",
 f"| Competencies with only compatibility/none families | {rc['competencyStatus']['compat-only']} | |",
 f"| Competencies with no family | {rc['competencyStatus']['no-families']} | |"]
L.append("\n**The '198' figure** equals the number of required competencies that have at least one kernel-backed or partially adapted family (115 with a kernel-backed family). It is not a count of competencies with complete verification: only 18 are fully kernel-backed, 129 have compatibility-mode families only, 9 have no family. (A separate count of distinct competency ids in the CBSE maths curriculum files is 139, of which 134 are among the 336.) The 667 compatibility families are a family count, not a competency count.\n")
L.append("\nThe matrix lists 1,090 family references for 1,078 distinct families (a family can serve more than one competency). Classification uses the existing `classifyAll` method (fixed sample parameters per arity), so 175 / 203 / 667 / 35 reproduce exactly. It is a sample-based classification of a family, not a proof about every question in its pool.\n")
L.append("## 2. By strand\n\n| Strand | Competencies | Family refs | Kernel | Partial | Compat/none | Pool problems | In kernel-backed families |\n|---|---|---|---|---|---|---|---|")
for k,s in S.items(): L.append(f"| {k} | {s[0]} | {s[1]} | {s[2]} | {s[3]} | {s[4]} | {s[5]} | {s[6]} ({100*s[6]/s[5]:.1f}%) |" if s[5] else f"| {k} | {s[0]} | {s[1]} | {s[2]} | {s[3]} | {s[4]} | 0 | – |")
L.append("\n## 3. Unverified step operations, by problem volume\n\nVolume is summed pool size of each family containing the operation (a family with several unverified ops is counted under each).\n\n| Op | Families | Pool problems |\n|---|---|---|")
for k,v in sorted(ops.items(),key=lambda kv:-kv[1][1])[:30]: L.append(f"| {k} | {v[0]} | {v[1]} |")
L.append("\n## 4. The 336 rows\n\nStatus: all-verified (every family kernel-backed), some-verified, compat-only, no-families. Volume = pool problems over the competency's families.\n\n| Competency | Gr | Strand | Fam | K | P | C/N | Volume | Verified share | Status | Families |\n|---|---|---|---|---|---|---|---|---|---|---|")
for r in sorted(R,key=lambda r:(r['strand'],r['id'])):
    fl=', '.join(r['families'][:6])+(f" +{len(r['families'])-6}" if len(r['families'])>6 else '')
    L.append(f"| {r['id']} | {r['grades'][0]}–{r['grades'][1]} | {r['strand']} | {r['nFamilies']} | {r['kernel']} | {r['partial']} | {r['compat']+r['none']} | {r['volume']} | {r['verifiedShare']:.0%} | {r['status']} | {fl} |")
open('tools/mathematics/core/audit/AUDIT-336.md','w').write('\n'.join(L)+'\n')
print(len(cb),len(cb&mat),anyv,anyk); print(open('tools/mathematics/core/audit/AUDIT-336.md').read().split('## 4.')[0][-3800:])
